mapper.select:


    v.period = #{q.period}
    AND v.status = #{q.status}
    AND v.source_type = #{q.sourceType}

        AND (v.voucher_no LIKE CONCAT('%', #{q.keyword}, '%') OR v.summary LIKE CONCAT('%', #{q.keyword}, '%')
             OR v.source_no LIKE CONCAT('%', #{q.keyword}, '%'))


        AND EXISTS (SELECT 1 FROM fin_voucher_entry e JOIN fin_account a ON a.id = e.account_id
                    JOIN fin_account p ON p.id = #{q.accountId}
                    WHERE e.voucher_id = v.id AND a.code LIKE CONCAT(p.code, '%'))


ORDER BY v.period DESC, v.voucher_seq DESC
